#pragma warning disable CA1725
using ClosedXML.Excel;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Warehouses;
namespace WhatsBiz.Infrastructure.Warehouses;
public sealed class WarehouseSpreadsheetService:IWarehouseSpreadsheetService{private static readonly string[] Headers=["Warehouse Code","Warehouse Name","Type Code","Manager Name","Email","Phone","Mobile","Capacity","Is Default","Is Active"];public byte[] Export(IReadOnlyCollection<Warehouse> rows){using var book=new XLWorkbook();var sheet=book.AddWorksheet("Warehouses");WriteHeaders(sheet);var row=2;foreach(var x in rows){sheet.Cell(row,1).Value=x.WarehouseCode;sheet.Cell(row,2).Value=x.WarehouseName;sheet.Cell(row,3).Value=x.WarehouseType?.TypeCode??"";sheet.Cell(row,4).Value=x.ManagerName;sheet.Cell(row,5).Value=x.Email;sheet.Cell(row,6).Value=x.Phone;sheet.Cell(row,7).Value=x.Mobile;sheet.Cell(row,8).Value=x.Capacity;sheet.Cell(row,9).Value=x.IsDefault;sheet.Cell(row,10).Value=x.IsActive;row++;}sheet.Columns().AdjustToContents();return Bytes(book);}public byte[] Template(){using var book=new XLWorkbook();var sheet=book.AddWorksheet("Warehouses");WriteHeaders(sheet);sheet.Cell(2,1).Value="WH-001";sheet.Cell(2,2).Value="Main Warehouse";sheet.Cell(2,3).Value="GENERAL";sheet.Cell(2,8).Value=1000;sheet.Cell(2,9).Value=true;sheet.Cell(2,10).Value=true;sheet.Columns().AdjustToContents();return Bytes(book);}public IReadOnlyCollection<WarehouseImportRow> Read(byte[] data){using var stream=new MemoryStream(data);using var book=new XLWorkbook(stream);var sheet=book.Worksheet(1);var rows=new List<WarehouseImportRow>();foreach(var row in sheet.RowsUsed().Skip(1)){if(string.IsNullOrWhiteSpace(row.Cell(1).GetString()))continue;rows.Add(new(row.RowNumber(),row.Cell(1).GetString().Trim(),row.Cell(2).GetString().Trim(),row.Cell(3).GetString().Trim(),Text(row,4),Text(row,5),Text(row,6),Text(row,7),row.Cell(8).TryGetValue<decimal>(out var capacity)?capacity:0,row.Cell(9).TryGetValue<bool>(out var isDefault)&&isDefault,!row.Cell(10).TryGetValue<bool>(out var active)||active));}return rows;}private static string? Text(IXLRow row,int column){var value=row.Cell(column).GetString().Trim();return value.Length==0?null:value;}private static void WriteHeaders(IXLWorksheet sheet){for(var i=0;i<Headers.Length;i++)sheet.Cell(1,i+1).Value=Headers[i];sheet.Row(1).Style.Font.Bold=true;}private static byte[] Bytes(XLWorkbook book){using var stream=new MemoryStream();book.SaveAs(stream);return stream.ToArray();}}
